  --bg-row-alt:rgba(0,0,0,.022);--bg-row-hover:rgba(0,0,0,.045);--bg-row-sel:rgba(63,88,214,.2);
  --bg-input:rgba(0,0,0,.05);--bg-chip:rgba(0,0,0,.06);--bg-control:rgba(0,0,0,.05);--bg-control-active:rgba(0,0,0,.1);--track:rgba(0,0,0,.1);--bg-modal:#f6f7fa;
  --text:#1a1c22;--text-dim:#5a616f;--text-faint:#646b7a;--border:rgba(0,0,0,.09);--border-strong:rgba(0,0,0,.14);--seg-empty:rgba(0,0,0,.08);--scrim:rgba(0,0,0,.32);
  --accent:#3F58D6;--on-accent:#fff;--on-red:#fff;--accent-press:#2E45B8;--accent-soft:rgba(63,88,214,.18);--green:#158A3C;--orange:#A85800;--red:#CE0E0E;--red-soft:rgba(206,14,14,.12);--yellow:#8A6D00;--purple:#7A3FD0;--teal:#0E7490;--indigo:#3F58D6;color-scheme:light}
html[data-theme="frost-dark"]{
  --bg-app:#15171d;--bg-window:#1e2027;--bg-bar:rgba(28,30,37,.72);--bg-sidebar:rgba(24,26,32,.72);--bg-content:#1c1e25;--bg-panel:rgba(40,43,53,.7);
  --bg-row-alt:rgba(255,255,255,.022);--bg-row-hover:rgba(255,255,255,.05);--bg-row-sel:rgba(138,162,255,.24);
  --bg-input:rgba(255,255,255,.07);--bg-chip:rgba(255,255,255,.08);--bg-control:rgba(255,255,255,.09);--bg-control-active:rgba(255,255,255,.16);--track:rgba(255,255,255,.1);--bg-modal:#252831;
  --text:#eef1f7;--text-dim:#9aa3b4;--text-faint:#8b94a8;--border:rgba(255,255,255,.09);--border-strong:rgba(255,255,255,.15);--seg-empty:rgba(255,255,255,.08);--scrim:rgba(0,0,0,.55);
