html[data-theme="dracula"]{
  --bg-app:#21222c;--bg-window:#282a36;--bg-bar:rgba(40,42,54,.82);--bg-sidebar:rgba(33,34,44,.9);--bg-content:#282a36;--bg-panel:rgba(52,55,70,.72);
