  --accent:#BD93F9;--on-accent:#12141a;--on-red:#12141a;--accent-press:#A97BF0;--accent-soft:rgba(189,147,249,.22);--green:#50FA7B;--orange:#FFB86C;--red:#FF6E6E;--red-soft:rgba(255,110,110,.16);--yellow:#F1FA8C;--purple:#FF79C6;--teal:#8BE9FD;--indigo:#BD93F9;color-scheme:dark}
html[data-theme="nord"]{
  --bg-app:#2b303b;--bg-window:#2e3440;--bg-bar:rgba(46,52,64,.82);--bg-sidebar:rgba(43,48,59,.9);--bg-content:#2e3440;--bg-panel:rgba(59,66,82,.72);
